// Writes every generated file listed in shared/CONTRACT.md ("Generated files"). Run: just sync-assets
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildWorker } from './build-worker.mjs';

const root = new URL('..', import.meta.url);
const at = (p) => fileURLToPath(new URL(p, root));
const read = (p) => fs.readFileSync(at(p), 'utf8');
const write = (p, text) => {
  fs.mkdirSync(at(p + '/..'), { recursive: true });
  fs.writeFileSync(at(p), text);
};

const HEADER = 'GENERATED by scripts/sync-assets — do not edit by hand';

// 1. CSS: tokens as custom properties, then the hand-written base.
const tokens = JSON.parse(read('shared/design-tokens.json'));
const groups = ['color', 'size', 'radius', 'font', 'motion'];
const vars = groups.flatMap((group) =>
  Object.entries(tokens[group]).map(([key, value]) => `  --hbv-${group}-${key}: ${value};`),
);
const css = `/* ${HEADER} */\n:root {\n${vars.join('\n')}\n}\n\n${read('shared/styles/listener.css')}`;
write('packages/react/src/styles.css', css);
write('crates/happybirthdayvalera/assets/listener.css', css);

// 2. The Whisper worker for the Dioxus web build.
const worker = `// ${HEADER}\n${await buildWorker()}`;
write('crates/happybirthdayvalera/assets/whisper-worker.js', worker);

// 3. JSON copies the crate reads with include_str!.
for (const name of ['locales', 'design-tokens', 'behavior', 'machine']) {
  fs.copyFileSync(at(`shared/${name}.json`), at(`crates/happybirthdayvalera/shared/${name}.json`));
}

// 4. The waveform fixture.
execFileSync(process.execPath, [at('scripts/wave-fixture.mjs')], { stdio: 'ignore' });

console.log(`styles.css ${css.length} bytes; whisper-worker.js ${(Buffer.byteLength(worker) / 1024).toFixed(0)} KiB`);
